<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,errorText,hasRole } from '../api'
import { usePageBounds,useLoad,useRequestKey } from '../composables'
import type { Page,Target,Runbook } from '../types'
import PageState from '../components/PageState.vue'
import PaginationBar from '../components/PaginationBar.vue'
import FilterToolbar from '../components/FilterToolbar.vue'
import AppIcon from '../components/AppIcon.vue'
type Book=Runbook&{targetName:string}
const route=useRoute(),router=useRouter(),targetId=ref(String(route.query.targetId||'')),targetPage=ref(0),targets=ref<Page<Target>|null>(null),page=ref(0),query=ref(''),sort=ref('created_desc'),creating=ref(false),title=ref(''),markdown=ref(''),busy=ref(false),saveError=ref(''),targetError=ref(''),key=useRequestKey()
const {data,loading,error,load}=useLoad(()=>api<Page<Book>>('/workspace/runbooks?'+new URLSearchParams({page:String(page.value),size:'20',q:query.value,sort:sort.value,...(targetId.value?{targetId:targetId.value}:{})})))
async function loadTargets(){targetError.value='';try{targets.value=await api<Page<Target>>(`/workspace/targets?page=${targetPage.value}&size=100&sort=name_asc`)}catch(e){targetError.value=errorText(e)}}
async function choose(){page.value=0;creating.value=false;saveError.value='';await router.replace({query:targetId.value?{targetId:targetId.value}:{}});await load()}
async function create(){if(!targetId.value)return;busy.value=true;saveError.value='';try{const body={title:title.value,markdown:markdown.value};const book=await api<Runbook>(`/targets/${targetId.value}/runbooks`,{method:'POST',body,key:key.forBody({targetId:targetId.value,...body})});await router.push('/runbooks/'+book.id)}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
usePageBounds(data,page,load)
let debounce:ReturnType<typeof setTimeout>|undefined
watch(query,()=>{clearTimeout(debounce);debounce=setTimeout(()=>{page.value=0;void load()},250)});watch(sort,()=>{page.value=0;void load()})
onMounted(()=>{void load();void loadTargets()});onUnmounted(()=>clearTimeout(debounce))
</script>
<template><div class="page-heading"><div><div class="eyebrow">Knowledge base</div><h1>运维知识库 <span v-if="data" class="heading-count">{{ data.total }}</span></h1><p>可发布的运行手册与冻结版本，为人工排查和 AI 诊断提供来源。</p></div><button v-if="hasRole('OPS_ADMIN')" class="btn primary" :disabled="!targetId" :title="!targetId?'先选择具体服务，再新建手册':undefined" @click="creating=!creating"><AppIcon name="plus" :size="16" />{{ creating?'收起新建':'新建手册' }}</button></div><section class="panel"><FilterToolbar v-model:query="query" v-model:sort="sort" placeholder="搜索手册标题或服务" :sorts="[{value:'created_desc',label:'最新在前'},{value:'name_asc',label:'标题 A → Z'},{value:'name_desc',label:'标题 Z → A'}]"><label class="compact-label"><span class="sr-only">手册服务目标</span><select v-model="targetId" aria-label="手册服务目标" @change="choose"><option value="">全部可见服务</option><option v-for="target in targets?.items" :key="target.id" :value="target.id">{{ target.name }}</option><option v-if="targetId&&!targets?.items.some(t=>t.id===targetId)" :value="targetId">当前服务 {{ targetId.slice(0,8) }}</option></select></label><button class="icon-button" aria-label="刷新知识库" :disabled="loading" @click="load"><AppIcon name="refresh" :size="16" /></button></FilterToolbar><div class="panel-footnote">知识库显示当前版本目录，不受全局时间范围限制。新建时请先选择具体服务。</div><div v-if="targetError" class="error-message" role="alert">服务选项加载失败：{{ targetError }}<button class="btn" @click="loadTargets">重试</button></div><PaginationBar v-if="targets&&targets.total>100" :page="targetPage" :size="100" :total="targets.total" @change="p=>{targetPage=p;loadTargets()}" /><form v-if="creating" class="inline-form" @submit.prevent="create"><h2>新建草稿</h2><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><label>手册标题<input v-model="title" required maxlength="160" /></label><label>Markdown 正文<textarea v-model="markdown" required maxlength="24000" rows="10" placeholder="# 观测&#10;先核对检查历史。&#10;## 排查&#10;人工比较上游和部署状态。"></textarea></label><p class="form-hint">发布时按标题分段，最多 5 段、每段 6,000 字；正文按文本展示。</p><div class="form-actions"><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'保存草稿' }}</button></div></form><PageState :loading="loading&&!data" :error="error" :empty="!!data&&!data.items.length" title="没有匹配的知识条目" description="可调整服务或关键词筛选；管理员可为具体服务创建并发布运行手册。" @retry="load"><div class="table-scroll" tabindex="0" aria-label="知识目录，可横向滚动"><table><thead><tr><th>手册</th><th>关联服务</th><th>发布版本</th><th>状态</th><th>草稿</th></tr></thead><tbody><tr v-for="book in data?.items" :key="book.id"><td><RouterLink :to="'/runbooks/'+book.id" class="row-title"><AppIcon name="book" :size="14" style="display:inline;margin-right:8px" />{{ book.title }}</RouterLink></td><td><RouterLink :to="'/targets/'+book.targetId" class="text-link">{{ book.targetName }}</RouterLink></td><td><span class="version-tag">{{ book.latestVersion?'v'+book.latestVersion:'尚未发布' }}</span></td><td><span class="status" :class="book.enabled?'good':'neutral'">{{ book.enabled?'启用':'已停用' }}</span></td><td class="muted">{{ book.hasUnpublishedChanges?'有未发布更改':'与发布版一致' }}</td></tr></tbody></table></div><PaginationBar v-if="data" :page="page" :size="20" :total="data.total" :loading="loading" @change="p=>{page=p;load()}" /></PageState></section></template>
